                            "observation must not repeat across layers: " + member.observationId());
                }
                total++;
            }
        }
        if (total > MAX_OBSERVATIONS) {
            throw ApiException.badRequest("at most " + MAX_OBSERVATIONS + " observations per estimate");
        }
    }

